INSERT INTO plans (id, plan_id, incident_id, plan_title, plan_content, generate_time, status, created_at, updated_at) VALUES
(1, 'plan-001', 'mock-0001', '地震应急方案-初版', '一、灾情概况\n本次地震发生在云南省昆明市，震级5.2级。\n\n二、响应措施\n1. 立即启动Ⅲ级应急响应\n2. 组织救援队伍赶赴现场\n3. 设置临时安置点\n4. 开展伤员救治\n\n三、资源调配\n调配救援队伍3支、医疗物资若干、运输车辆10台。', '2026-07-20 10:30:00', 'approved', '2026-07-20 10:30:00', '2026-07-20 11:00:00'),
(2, 'plan-002', 'mock-0001', '地震应急方案-修订版', '一、灾情更新\n根据最新灾情评估，调整响应级别为Ⅱ级。\n\n二、调整措施\n1. 提升应急响应级别至Ⅱ级\n2. 增派救援力量\n3. 扩大疏散范围', '2026-07-21 14:00:00', 'draft', '2026-07-21 14:00:00', '2026-07-21 14:00:00'),
(3, 'DP-001', 'mock-0001', '处置方案', '一、灾情概况\n震中位于昆明市某区域，震级5.2级。\n二、响应措施\n1. 启动Ⅲ级应急响应\n2. 组织救援队伍赶赴现场\n3. 设置临时安置点', '2026-07-20 10:30:00', 'accepted', '2026-07-20 10:30:00', '2026-07-20 14:00:00'),
(4, 'DP-002', 'mock-0002', '处置方案', '一、灾情概况\n泥石流发生在昭通市某山区。\n二、响应措施\n1. 组织群众转移\n2. 封闭危险路段\n3. 开展搜救工作', '2026-07-21 08:00:00', 'submitted', '2026-07-21 08:00:00', '2026-07-21 09:00:00'),
(5, 'DP-003', 'mock-0003', '处置方案', '一、灾情概况\n洪涝灾害影响大理州多个乡镇。\n二、响应措施\n1. 启动防汛应急响应\n2. 调配救援船只\n3. 转移低洼地区群众', '2026-07-21 15:00:00', 'draft', '2026-07-21 15:00:00', '2026-07-21 15:00:00'),
(6, 'DP-004', 'mock-0001', '处置方案', '一、灾情更新\n根据余震情况，调整响应级别。\n二、调整措施\n1. 提升响应级别至Ⅱ级\n2. 增派救援力量', '2026-07-22 07:00:00', 'rejected', '2026-07-22 07:00:00', '2026-07-22 10:00:00');
